import type { Study } from "./dirTypes";

/** Stage 6 actions: compile the DIR, then download the report or GIS export. */
export default function DirReportActions({
  study,
  allReady,
  busy,
  onCompile,
  onDownload,
  onExport,
}: {
  study: Study;
  allReady: boolean;
  busy: boolean;
  onCompile: () => void;
  onDownload: () => void;
  onExport: () => void;
}) {
  const completed = study.steps["6"]?.status === "completed";
  return (
    <div className="flex flex-wrap gap-2">
      <button
        type="button"
        disabled={busy || !allReady || completed}
        className="rounded bg-primary-600 px-3 py-2 text-sm text-white disabled:opacity-50"
        onClick={onCompile}
      >
        Compile DIR
      </button>
      {completed && (
        <button
          type="button"
          className="rounded border px-3 py-2 text-sm"
          onClick={onDownload}
        >
          Download report
        </button>
      )}
      {completed &&
        (study.output_line_layer_id || study.output_node_layer_id) && (
          <button
            type="button"
            className="rounded border px-3 py-2 text-sm"
            onClick={onExport}
          >
            Export DIR GIS
          </button>
        )}
    </div>
  );
}

