def _previous_ready(study: DirStudy, code: str) -> None:
    for prior in OPTIONAL[:OPTIONAL.index(code)]:
        if cast(dict[str, object], study.steps[prior])["status"] not in {"completed", "skipped"}:
            _fail(409, f"Complete or skip Stage {prior} first.")


def _initial_steps() -> dict[str, dict[str, object]]:
    return cast(dict[str, dict[str, object]], {
        code: {
            "code": code, "status": "pending", "old_layer_ids": [], "evidence_layer_ids": [],
            "selected_dataset_keys": [], "skip_reason": None, "summary": None, "finding_count": 0,
            "blocking_reason": None, "grade_summary": None, "grade_d_feature_ids": [],
            "service_plan_confirmed": False, "confirmed_by": None, "confirmed_at": None,
            "analysis_method": None, "missing_final_count": 0, "missing_original_count": 0,
        }
        for code in (*OPTIONAL, "6")
    })


def _dataset_map(layers: list[ProjectLayer]) -> dict[str, DirDataset]:
    return {item.key: item for item in base._category_datasets(layers, {
        "S5A_CUP", "S5_GCUP", "S1_TOPO", "S2_EML", "S3_MCGPR", "S4_TTR",
    })}


def _stage_two_match_index(final: list[base._Feature]) -> tuple[
    dict[tuple[str, tuple[str, str, str, str]], list[base._Feature]],
    dict[str, tuple[STRtree, list[base._Feature]]],
]:
    keyed: dict[tuple[str, tuple[str, str, str, str]], list[base._Feature]] = {}
    spatial: dict[str, tuple[STRtree, list[base._Feature]]] = {}
    for kind in ("manhole", "alignment", "node"):
        group = [item for item in final if item.kind == kind]
        if group:
            spatial[kind] = (STRtree([item.geom for item in group]), group)
            for item in group:
                if item.match_key:
                    keyed.setdefault((kind, item.match_key), []).append(item)
    return keyed, spatial


def _search_box(geom: BaseGeometry, radius: float) -> Polygon:
    west, south, east, north = geom.bounds
    return box(west - radius, south - radius, east + radius, north + radius)


def _tree_indices(tree: STRtree, geometry: BaseGeometry) -> Iterable[int]:
    return cast(Iterable[int], cast(object, tree.query(geometry)))


def _stage_two_match(
    old: base._Feature,
    keyed: dict[tuple[str, tuple[str, str, str, str]], list[base._Feature]],
    spatial: dict[str, tuple[STRtree, list[base._Feature]]],
) -> base._Feature | None:
    keyed_group = keyed.get((old.kind, old.match_key), []) if old.match_key else []
    if keyed_group:
        return min(keyed_group, key=lambda item: old.geom.distance(item.geom))
    group = spatial.get(old.kind)
    if group is None:
        return None
    tree, features = group
    candidates = [
        features[index] for index in _tree_indices(tree, _search_box(old.geom, 10))
        if (not old.owner or not features[index].owner or old.owner == features[index].owner)
        and (not old.infr_type or not features[index].infr_type or old.infr_type == features[index].infr_type)
        and old.geom.distance(features[index].geom) <= 10
    ]
    return min(candidates, key=lambda item: old.geom.distance(item.geom)) if candidates else None


def _reference_eligible(source: base._Feature, target: base._Feature) -> bool:
    return source.kind == target.kind or (
        target.kind == "manhole" and source.geom_type == "Polygon" and not source.feat_type
    )


def _survey_cover(feature: base._Feature) -> bool:
    if feature.geom_type != "Point":
        return False
    code = (feature.feat_type or "").strip().upper()
    name = (feature.layer_name or "").strip().upper()
    return code in {"MH", "MHOL", "MH--", "MHST"} or "MANHOLE" in name or "COVER" in name


def _alignment_measurement_points(source: BaseGeometry, target: BaseGeometry) -> tuple[Point, Point]:
    """Measure final alignment vertices against the original baseline geometry."""
    if isinstance(target, LineString):
        coordinates = target.coords
    elif isinstance(target, MultiLineString):
        coordinates = (coordinate for part in target.geoms for coordinate in part.coords)
    else:
        raise ValueError("Alignment target must be a line.")
    vertex = max((Point(coordinate[:2]) for coordinate in coordinates), key=lambda point: point.distance(source))
    if vertex.distance(source) == 0:
        return vertex, vertex
    return vertex, nearest_points(vertex, force_2d(source))[1]


def _alignment_offset(source: BaseGeometry, target: BaseGeometry) -> float:
    start, _ = _alignment_measurement_points(source, target)
    return start.distance(source)


def _stage_two_measurement_points(source: BaseGeometry, target: BaseGeometry) -> tuple[Point, Point]:
    if isinstance(target, (LineString, MultiLineString)):
        return _alignment_measurement_points(source, target)
    return target.centroid, source.centroid


def _stage_two_measurement_geometry(source: BaseGeometry, target: BaseGeometry) -> dict[str, object]:
    start, end = _stage_two_measurement_points(source, target)
    return dict(mapping(LineString([start, end])))


def _stage_two_distance(source: base._Feature, target: base._Feature) -> float:
    start, end = _stage_two_measurement_points(source.geom, target.geom)
    return start.distance(source.geom) if target.kind == "alignment" else start.distance(end)


def _full_spatial_overlap(source: base._Feature, target: base._Feature, threshold: float) -> bool:
    if not source.geom.is_valid or not target.geom.is_valid or source.geom.area <= 0 or target.geom.area <= 0:
        return False
    if target.owner and source.owner and target.owner != source.owner:
        return False
    if target.infr_type and source.infr_type and target.infr_type != source.infr_type:
        return False
    if target.geom.centroid.distance(source.geom.centroid) > threshold:
        return False
    intersection = target.geom.intersection(source.geom).area
    union = target.geom.area + source.geom.area - intersection
    return union > 0 and intersection / union >= 0.9


def _auto_confirm_stage_two(
    outcome: str, source: base._Feature | None, target: base._Feature, threshold: float,
) -> bool:
    if outcome == "within_tolerance":
        return True
    return bool(
        target.kind == "manhole" and source is not None and source.geom_type == "Polygon"
        and ((source.kind == "manhole" and source.match_key is not None and source.match_key == target.match_key)
             or _full_spatial_overlap(source, target, threshold))
    )


def _full_spatial_manhole_match(
    target: base._Feature,
    index: tuple[STRtree, list[base._Feature]] | None,
    threshold: float,
    used_ids: set[UUID],
) -> base._Feature | None:
    """Use an uncoded polygon only when one baseline polygon closely matches its shape."""
    if index is None or not target.geom.is_valid or target.geom.area <= 0:
        return None
    tree, features = index
    matches: list[base._Feature] = []
    for candidate_index in _tree_indices(tree, target.geom):
        source = features[candidate_index]
        if source.id in used_ids or not _full_spatial_overlap(source, target, threshold):
            continue
        matches.append(source)
    return matches[0] if len(matches) == 1 else None


def _stage_two_candidates(
    old: list[base._Feature], final: list[base._Feature], evidence: list[base._Feature],
    threshold: float,
) -> tuple[list[dict[str, object]], int, int]:
    """Match final GeoCUP to original geometry; survey covers are optional evidence."""
    eligible_old = [item for item in old if item.kind in {"manhole", "alignment", "node"}]
    eligible_final = [item for item in final if item.kind in {"manhole", "alignment", "node"}]
    keyed_old, spatial_old = _stage_two_match_index(eligible_old)
    uncoded_polygons = [item for item in eligible_old if item.geom_type == "Polygon" and not item.feat_type and not item.geom.is_empty]
    uncoded_index = (STRtree([item.geom for item in uncoded_polygons]), uncoded_polygons) if uncoded_polygons else None
    cover_index = _stage_two_evidence_index([item for item in evidence if _survey_cover(item)]).get("Point")
    matched_old_ids: set[UUID] = set()
    candidates: list[dict[str, object]] = []
    missing_original = 0
    for target in eligible_final:
        source = _stage_two_match(target, keyed_old, spatial_old)
        if source is None and target.kind == "manhole":
            source = _full_spatial_manhole_match(target, uncoded_index, threshold, matched_old_ids)
        covers = [
            item for item in _stage_two_nearby(target.geom.centroid, cover_index, 32, 10)
            if (not target.owner or not item.owner or target.owner == item.owner)
            and (not target.infr_type or not item.infr_type or target.infr_type == item.infr_type)
            and (not target.infid or not item.infid or target.infid == item.infid)
        ][:8] if target.kind == "manhole" else []
        if source is None:
            missing_original += 1
            if target.kind == "manhole":
                candidates.append({
                    "source": None, "target": target, "covers": covers,
                    "distance": None, "outcome": "unverified",
                })
            continue
        matched_old_ids.add(source.id)
        if target.kind == "node":
            continue
        distance = _stage_two_distance(source, target)
        candidates.append({
            "source": source, "target": target, "covers": covers,
            "distance": distance, "outcome": "deviated" if base._is_deviation(round(distance, 3), threshold) else "within_tolerance",
        })
    missing_final = len(eligible_old) - len(matched_old_ids)
    return candidates, missing_final, missing_original


def _stage_two_evidence_index(evidence: list[base._Feature]) -> dict[str, tuple[STRtree, list[base._Feature]]]:
    groups = {"all": evidence, "Point": [item for item in evidence if item.geom_type == "Point"]}
    return {
        key: (STRtree([item.geom for item in group]), group)
        for key, group in groups.items() if group
    }


