async def create(db: AsyncSession, project_id: UUID, request: DirWorkflowV3Create) -> DirStudyResponse:
    layers = await base._project_layers(db, project_id)
    datasets = _dataset_map(layers)
    final = datasets.get(request.final_dataset_key)
    if final is None or final.category != "S5_GCUP":
        _fail(422, "Choose one final S5_GCUP dataset.")
    if request.baseline_dataset_key is not None:
        legacy_baseline = datasets.get(request.baseline_dataset_key)
        if legacy_baseline is None or legacy_baseline.category not in {"S5A_CUP", "S5_GCUP"}:
            _fail(422, "Choose an original CUP or GeoCUP baseline category and version.")
        baseline_category = legacy_baseline.category
        baseline_version = legacy_baseline.version
    else:
        baseline_category = request.baseline_category
        baseline_version = request.baseline_version
    baseline_layers = sorted(
        (
            layer for layer in layers
            if (layer.layer_category or "").upper() == baseline_category and layer.version == baseline_version
        ),
        key=lambda layer: str(layer.id),
    )
    if not baseline_layers:
        _fail(422, "Choose an existing CUP or GeoCUP baseline category and version.")
    baseline_ids = [layer.id for layer in baseline_layers]
    if set(baseline_ids) & set(final.layer_ids):
        _fail(422, "The baseline category and version include the selected final GeoCUP import.")
    if all(layer.feature_geom_type == "Annotation" for layer in baseline_layers):
        _fail(422, "The baseline has no usable geometry layers.")
    if not request.baseline_is_original:
        _fail(422, "Confirm that the baseline represents original geometry.")
    versions = [base._version_key(item.version) for item in datasets.values() if item.category == "S5_GCUP"]
    if base._version_key(final.version) != max((value for value in versions if value is not None), default=None):
        _fail(422, "Choose a GeoCUP dataset with the highest version number.")
    layer_map = {item.id: item for item in layers}
    area_mode = request.working_area.mode
    area_layer_ids = request.working_area.layer_ids
    if len(area_layer_ids) != len(set(area_layer_ids)):
        _fail(422, "Working area layer IDs must be unique.")
    if area_mode not in {"topo_layers", "boundary_layer"} and area_layer_ids:
        _fail(422, "This working area cannot select layers.")
    if area_mode != "drawn_box" and request.working_area.bbox is not None:
        _fail(422, "Only a drawn box working area can provide box coordinates.")
    area = None
    if area_mode == "whole":
        final_features = [feature for item in final.layer_ids for feature in await base._load_features(db, [layer_map[item]])]
        geometries = [force_2d(feature.geom) for feature in final_features if not feature.geom.is_empty]
        if not geometries or any(not geometry.is_valid for geometry in geometries):
            _fail(422, "The final GeoCUP needs valid geometry to define the working area.")
        area = _geocup_working_area(geometries)
    elif area_mode == "project_boundary":
        project = (await db.execute(select(Project).where(Project.id == project_id))).scalar_one()
        if project.boundary_box is None:
            _fail(422, "The project boundary box is missing.")
        area = force_2d(to_shape(cast(WKBElement, cast(object, project.boundary_box))))
    elif area_mode == "drawn_box":
        bounds = request.working_area.bbox
        if bounds is None:
            _fail(422, "Draw a working area box first.")
        (first_lng, first_lat), (second_lng, second_lat) = bounds
        west, east = sorted((first_lng, second_lng))
        south, north = sorted((first_lat, second_lat))
        if not (-180 <= west < east <= 180 and -90 <= south < north <= 90):
            _fail(422, "Draw a valid working area box.")
        transformer = Transformer.from_crs(4326, 3414, always_xy=True)
        area = transform(transformer.transform, box(west, south, east, north))
    elif area_mode == "boundary_layer":
        if len(area_layer_ids) != 1:
            _fail(422, "Select one project boundary layer.")
        boundary_id = area_layer_ids[0]
        if boundary_id not in layer_map or layer_map[boundary_id].feature_geom_type != "Polygon":
            _fail(422, "Select a project polygon boundary layer.")
        registered = (await db.execute(select(ProjectBoundsBoxLayer.layer_id).where(
            ProjectBoundsBoxLayer.project_id == project_id, ProjectBoundsBoxLayer.layer_id == boundary_id,
        ))).scalar_one_or_none()
        if registered is None:
            _fail(422, "The selected layer is not a project boundary layer.")
        await ProjectService.assert_boundary_is_fresh(db, boundary_id)
        polygons = [force_2d(feature.geom) for feature in await base._load_features(db, [layer_map[boundary_id]])]
        if not polygons or any(not polygon.is_valid or polygon.geom_type not in {"Polygon", "MultiPolygon"} for polygon in polygons):
            _fail(422, "The project boundary layer needs valid polygon geometry.")
        area = unary_union(polygons)
    elif area_mode == "topo_layers":
        if not area_layer_ids:
            _fail(422, "Select at least one TOPO polygon layer.")
        if any(item not in layer_map or (layer_map[item].layer_category or "").upper() != "S1_TOPO" or layer_map[item].feature_geom_type != "Polygon" for item in area_layer_ids):
            _fail(422, "Working area layers must be project TOPO polygon layers.")
        polygons = [force_2d(feature.geom) for item in area_layer_ids for feature in await base._load_features(db, [layer_map[item]])]
        if not polygons or any(not polygon.is_valid or polygon.geom_type not in {"Polygon", "MultiPolygon"} for polygon in polygons):
            _fail(422, "TOPO working area needs valid polygon geometry.")
        area = unary_union(polygons)
    if area is not None:
        if area.is_empty or not area.is_valid or area.geom_type not in {"Polygon", "MultiPolygon"}:
            _fail(422, "Working area needs valid polygon geometry.")
        if not isinstance(area, (Polygon, MultiPolygon)):
            _fail(422, "Working area needs polygon geometry.")
        if isinstance(area, Polygon):
            area = MultiPolygon([area])
    selected_ids = set(final.layer_ids) | set(baseline_ids)
    if any(layer_map[item].feature_geom_type == "Annotation" for item in final.layer_ids):
        _fail(422, "The selected final dataset must contain usable geometry.")
    hashes = {str(item): base._source_hash(await base._load_features(db, [layer_map[item]])) for item in selected_ids | set(area_layer_ids)}
    if area is not None:
        final_features = [feature for item in final.layer_ids for feature in await base._load_features(db, [layer_map[item]])]
        if not any(area.intersects(feature.geom) for feature in final_features):
            _fail(422, "The working area has no final GeoCUP features.")
    study = DirStudy(
        project_id=project_id, workflow_version=3, new_dataset_key=final.key,
        baseline_dataset_key=sha256(f"baseline:{baseline_category}:{baseline_version}".encode()).hexdigest(),
        baseline_category=baseline_category, baseline_is_original=True,
        working_area_mode=area_mode, working_area_layer_ids=area_layer_ids,
        working_area_geom=from_shape(area, srid=3414) if area is not None else None,
        old_version=baseline_version, new_version=final.version,
        old_layer_ids=baseline_ids, new_layer_ids=final.layer_ids,
        evidence_layer_ids=[], source_hashes=hashes, steps=_initial_steps(),
        status="draft", revision=1,
    )
    db.add(study)
    await db.commit()
    return base._study_response(study)


async def delete_workflow(db: AsyncSession, study: DirStudy) -> None:
    if study.workflow_version != 3:
        _fail(404, "DIR workflow not found.")
    await base._delete_generated_layer(db, study, study.output_line_layer_id, "Line")
    await base._delete_generated_layer(db, study, study.output_node_layer_id, "Polygon")
    await db.delete(study)
    await db.commit()

async def analyze(db: AsyncSession, study: DirStudy, code: str) -> DirStudyResponse:
    state = _state(study, code)
    _previous_ready(study, code)
    if study.status == "generated" or state["status"] in {"completed", "skipped"} or state.get("finding_count"):
        _fail(409, "Change sources before analyzing this stage again.")
    if code in {"3", "4"} and not state["selected_dataset_keys"]:
        _fail(422, f"Select evidence datasets for Stage {code}, or skip it.")
    data = await base._check_sources(db, study)
    old = base._study_features_for(study, study.old_layer_ids, data)
    final = base._study_features_for(study, study.new_layer_ids, data)
    evidence_ids = [UUID(value) for value in cast(list[str], state["evidence_layer_ids"])]
    evidence = base._study_features_for(study, evidence_ids, data)
    steps = {key: dict(cast(dict[str, object], value)) for key, value in study.steps.items()}
    _ = await db.execute(delete(DirFinding).where(DirFinding.study_id == study.id, DirFinding.step_code == code))
    if code == "1":
        summary = v2._grade_summary(final)
        steps[code].update(
            status="pending", grade_summary=summary.model_dump(),
            summary=f"{summary.total} GeoCUP records; {summary.missing} without grade.",
            blocking_reason="Confirm the grade review before continuing.",
        )
    elif code == "5":
        alignments = [item for item in final if item.kind == "alignment"]
        missing = sum(v2._normalized_grade(item.grade) is None for item in alignments)
        summary = (f"Audited {len(alignments)} final GeoCUP alignments; {missing} have no source grade. See report."
                   if missing else f"Validated {len(alignments)} graded final alignments.")
        steps[code].update(status="completed", summary=summary, blocking_reason=None)
    else:
        threshold = await base._dir_threshold(db)
        findings: list[DirFinding] = []
        missing_final = missing_original = 0
        if code == "2":
            candidates, missing_final, missing_original = _stage_two_candidates(old, final, evidence, threshold)
            for candidate in candidates:
                source = cast(base._Feature | None, candidate["source"])
                target = cast(base._Feature, candidate["target"])
                covers = cast(list[base._Feature], candidate["covers"])
                distance = cast(float | None, candidate["distance"])
                outcome = cast(str, candidate["outcome"])
                measured = round(distance, 3) if distance is not None else None
                auto_confirmed = _auto_confirm_stage_two(outcome, source, target, threshold)
                finding = DirFinding(
                    study_id=study.id, step_code="2", kind=target.kind,
                    old_layer_id=source.layer_id if source else None,
                    old_feature_id=source.id if source else None,
                    new_feature_ids=[target.id],
                    evidence_feature_ids=[item.id for item in covers],
                    owner_code=(source.owner if source else None) or target.owner,
                    suggested_distance_m=measured,
                    measured_distance_m=measured if auto_confirmed else None,
                    outcome=outcome, grade=target.grade,
                    correction_required=outcome == "deviated", reviewed=auto_confirmed,
                    reviewed_at=datetime.now(UTC) if auto_confirmed else None, revision=1,
                )
                db.add(finding)
                findings.append(finding)
            steps[code].update(
                analysis_method="geocup_anchor_v2", missing_final_count=missing_final,
                missing_original_count=missing_original,
            )
        else:
            prior = []
            if code == "4":
                prior = list((await db.execute(select(DirFinding).where(DirFinding.study_id == study.id, DirFinding.step_code == "3"))).scalars().all())
            prior_by_new = {item.new_feature_ids[0]: item for item in prior if item.reviewed and len(item.new_feature_ids) == 1}
            for target in (item for item in final if item.kind == "alignment"):
                nearby = _nearby_evidence(target, evidence, threshold)
                if not nearby:
                    continue
                coverage = v2._coverage(target, nearby, threshold)
                if code == "3":
                    grade = v2._suggest_grade("4A", target, coverage, coverage, False)
                else:
                    previous = prior_by_new.get(target.id)
                    noninvasive = float(previous.validated_length_m or previous.suggested_length_m or 0) if previous else 0.0
                    grade = v2._suggest_grade("4A", target, max(noninvasive, coverage), noninvasive, True)
                finding = DirFinding(
                    study_id=study.id, step_code=code, kind="alignment", old_layer_id=None,
                    old_feature_id=None, new_feature_ids=[target.id],
                    evidence_feature_ids=[item.id for item in nearby], owner_code=target.owner,
                    suggested_length_m=round(coverage, 3), outcome="unverified", grade=grade,
                    correction_required=False, reviewed=False, revision=1,
                )
                db.add(finding)
                findings.append(finding)
        needs_review = any(not finding.reviewed for finding in findings)
        steps[code].update(
            status="pending" if needs_review else "completed", finding_count=len(findings),
            summary=(f"{len(findings)} GeoCUP review records; {missing_final} original features absent from GeoCUP; "
                     + f"{missing_original} GeoCUP features absent from original service plans."
                     if code == "2" else f"{len(findings)} findings proposed from {len(evidence)} evidence features."),
            blocking_reason="Review every finding to complete this stage." if needs_review else None,
        )
    study.steps = cast(dict[str, object], steps)
    study.status = "review"
    study.revision += 1
    await db.commit()
    return base._study_response(study)


async def confirm_stage_one(db: AsyncSession, study: DirStudy, request: DirStepOneConfirm, reviewer_id: UUID) -> DirStudyResponse:
    state = _state(study, "1")
    if state["status"] != "pending" or state["grade_summary"] is None or study.status == "generated":
        _fail(409, "Analyze Stage 1 before confirming it.")
    if study.revision != request.expected_revision:
        _fail(409, "DIR workflow changed. Reload it before confirming Stage 1.")
    data = await base._check_sources(db, study)
    final = base._study_features_for(study, study.new_layer_ids, data)
    baseline = base._study_features_for(study, study.old_layer_ids, data)

async def confirm_stage_three_evidence(
    db: AsyncSession, study: DirStudy, *, expected_revision: int, reviewer_id: UUID,
) -> DirStudyResponse:
    """Confirm every pending Stage 3 finding using its saved evidence."""
    state = _state(study, "3")
    if study.status == "generated" or state["status"] != "pending" or not state["finding_count"]:
        _fail(409, "Analyze Stage 3 before confirming its evidence.")
    if study.revision != expected_revision:
        _fail(409, "DIR workflow changed. Reload it before confirming Stage 3.")
    data = await base._check_sources(db, study)
    final = {item.id: item for item in base._study_features_for(study, study.new_layer_ids, data)}
    evidence = {item.id for item in base._study_features_for(
        study, [UUID(value) for value in cast(list[str], state["evidence_layer_ids"])], data,
    )}
    findings = (await db.execute(select(DirFinding).where(
        DirFinding.study_id == study.id, DirFinding.step_code == "3",
    ).with_for_update())).scalars().all()
    pending = [finding for finding in findings if not finding.reviewed]
    for finding in pending:
        length = finding.validated_length_m if finding.validated_length_m is not None else finding.suggested_length_m
        if (finding.kind != "alignment" or not finding.new_feature_ids or not finding.evidence_feature_ids
            or len(finding.new_feature_ids) != len(set(finding.new_feature_ids))
            or len(finding.evidence_feature_ids) != len(set(finding.evidence_feature_ids))
            or any(item not in final or final[item].kind != finding.kind for item in finding.new_feature_ids)
            or any(item not in evidence for item in finding.evidence_feature_ids)
            or length is None or len(finding.new_feature_ids) != 1
            or length < 0 or length > final[finding.new_feature_ids[0]].geom.length + 0.001):
            _fail(422, "A Stage 3 finding has invalid saved evidence. Review it individually.")
    reviewed_at = datetime.now(UTC)
    for finding in pending:
        finding.outcome = "within_tolerance"
        finding.correction_required = False
        finding.validated_length_m = finding.validated_length_m if finding.validated_length_m is not None else finding.suggested_length_m
        finding.reviewed = True
        finding.reviewed_by = reviewer_id
        finding.reviewed_at = reviewed_at
        finding.revision += 1
    steps = {key: dict(cast(dict[str, object], value)) for key, value in study.steps.items()}
    steps["3"].update(status="completed", blocking_reason=None)
    study.steps = cast(dict[str, object], steps)
    study.revision += 1
    await db.commit()
    return base._study_response(study)


async def review(
    db: AsyncSession, study: DirStudy, finding_id: UUID,
    *, expected_revision: int, outcome: str, measured_distance_m: float | None,
    correction_required: bool, new_feature_ids: list[UUID] | None,
    evidence_feature_ids: list[UUID] | None, grade: str | None,
    validated_length_m: float | None, reviewer_id: UUID,
) -> DirStudyResponse:
    if study.workflow_version != 3 or study.status == "generated":
        _fail(409, "This finding cannot be changed.")
    finding = (await db.execute(select(DirFinding).where(DirFinding.id == finding_id, DirFinding.study_id == study.id).with_for_update())).scalar_one_or_none()
    if finding is None or finding.step_code not in {"2", "3", "4"}:
        _fail(404, "DIR stage finding not found.")
    if finding.revision != expected_revision:
        _fail(409, "DIR finding changed. Reload it before saving.")
    state = _state(study, finding.step_code)
    if outcome == "rejected" and (
        finding.step_code != "2" or measured_distance_m is not None or correction_required
        or new_feature_ids is not None or evidence_feature_ids is not None
        or grade is not None or validated_length_m is not None
    ):
        _fail(422, "Reject a Stage 2 finding without a distance, correction, or source changes.")
    data = await base._check_sources(db, study)
    final = {item.id: item for item in base._study_features_for(study, study.new_layer_ids, data)}
    evidence = {item.id: item for item in base._study_features_for(study, [UUID(value) for value in cast(list[str], state["evidence_layer_ids"])], data)}
    if new_feature_ids is not None:
        if len(new_feature_ids) != len(set(new_feature_ids)) or not set(new_feature_ids).issubset(final):
            _fail(422, "Choose unique final GeoCUP feature IDs from this study.")
        if finding.step_code == "2" and state.get("analysis_method") == "geocup_anchor_v2" and new_feature_ids != finding.new_feature_ids:
            _fail(422, "The Stage 2 GeoCUP anchor cannot change during review.")
        if any(final[item].kind != finding.kind for item in new_feature_ids):
            _fail(422, "Matched features must have the same kind.")
        finding.new_feature_ids = new_feature_ids
    if evidence_feature_ids is not None:
        if len(evidence_feature_ids) != len(set(evidence_feature_ids)) or not set(evidence_feature_ids).issubset(evidence):
            _fail(422, "Choose unique evidence feature IDs from this stage.")
        finding.evidence_feature_ids = evidence_feature_ids
    if finding.step_code == "2" and outcome != "rejected":
        if grade is not None or validated_length_m is not None:
            _fail(422, "TOPO review does not assign an investigation grade or coverage.")
        if state.get("analysis_method") == "geocup_anchor_v2":
            if not finding.old_feature_id or len(finding.new_feature_ids) != 1 or outcome not in {"within_tolerance", "deviated"}:
                _fail(422, "Confirm one GeoCUP and original feature pair.")
            if finding.kind == "manhole" and any(not _survey_cover(evidence[item]) for item in finding.evidence_feature_ids):
                _fail(422, "Select only surveyed manhole covers as TOPO evidence.")
            if measured_distance_m is None:
                _fail(422, "Confirm the measured distance.")
            expected = "deviated" if base._is_deviation(measured_distance_m, await base._dir_threshold(db)) else "within_tolerance"
            if outcome != expected or correction_required != (outcome == "deviated"):
                _fail(422, "The outcome or correction does not match the DIR deviation rule.")
        else:
            allowed = {"within_tolerance", "not_found"} if finding.kind == "node" else {"within_tolerance", "deviated", "not_found"} if finding.old_feature_id else {"additional"}
