async def compile_workflow(db: AsyncSession, study: DirStudy):
    if study.workflow_version != 3:
        _fail(404, "DIR workflow not found.")
    for code in OPTIONAL:
        if cast(dict[str, object], study.steps[code])["status"] not in {"completed", "skipped"}:
            _fail(409, f"Complete or skip Stage {code} before Stage 6.")
    result = await base.generate_dir(db, study)
    steps = {key: dict(cast(dict[str, object], value)) for key, value in study.steps.items()}
    note = "No independent original baseline; no Grade E geometry compiled." if not base._independent_baseline(study) else f"Compiled {result.dir_feature_count} inaccurate legacy features."
    steps["6"].update(status="completed", summary=note, finding_count=result.dir_feature_count)
    study.steps = cast(dict[str, object], steps)
    study.revision += 1
    await db.commit()
    return result

async def generate_dir(db: AsyncSession, study: DirStudy) -> DirGenerateResponse:
    workflow_version = getattr(study, "workflow_version", 1)
    if study.status not in ({"draft", "review", "generated"} if workflow_version in {2, 3} else {"review", "generated"}):
        _fail(409, "Analyze and review the study before generation.")
    data = await _check_sources(db, study)
    all_findings = list((await db.execute(select(DirFinding).where(DirFinding.study_id == study.id))).scalars().all())
    if (not all_findings and workflow_version == 1) or any(not finding.reviewed for finding in all_findings):
        _fail(409, "Confirm every finding before generating DIR.")
    if workflow_version == 3:
        independent = _independent_baseline(study)
        findings = [finding for finding in all_findings if finding.step_code == "2" and finding.kind != "node" and finding.outcome != "rejected"] if independent else []
        if cast(dict[str, object], study.steps["2"]).get("analysis_method") == "geocup_anchor_v2":
            if any(not finding.old_feature_id or len(finding.new_feature_ids) != 1 or finding.outcome not in {"within_tolerance", "deviated"} for finding in findings):
                _fail(409, "Stage 2 has an invalid GeoCUP comparison.")
    else:
        findings = [finding for finding in all_findings if finding.step_code in {"2", "3"}] if workflow_version == 2 else all_findings
    old_features = {feature.id: feature for feature in _study_features_for(study, study.old_layer_ids, data)}
    new_features = {feature.id: feature for feature in _study_features_for(study, study.new_layer_ids, data)}
    matched_new: set[UUID] = set()
    for finding in findings:
        if finding.old_feature_id and finding.old_feature_id not in old_features:
            _fail(409, "An old feature is missing from the study.")
        if not set(finding.new_feature_ids).issubset(new_features):
            _fail(409, "A new feature is missing from the study.")
        if finding.outcome == "additional" and set(finding.new_feature_ids) & matched_new:
            _fail(409, "An additional manhole is also linked to an old feature.")
        if finding.old_feature_id:
            matched_new.update(finding.new_feature_ids)
    additional_ids = {feature_id for finding in findings if finding.outcome == "additional" for feature_id in finding.new_feature_ids}
    if additional_ids & matched_new:
        _fail(409, "A new manhole has conflicting findings.")
    threshold = await _dir_threshold(db)
    bad_old: list[_Feature] = []
    included_old_ids: set[UUID] = set()
    output_findings_by_old_id: dict[UUID, list[DirFinding]] = defaultdict(list)
    for finding in findings:
        if finding.old_feature_id is None:
            continue
        if finding.outcome == "deviated":
            if finding.measured_distance_m is None or not _is_deviation(float(finding.measured_distance_m), threshold):
                _fail(409, "A deviation no longer meets the DIR rule.")
            output_findings_by_old_id[finding.old_feature_id].append(finding)
            if finding.old_feature_id not in included_old_ids:
                bad_old.append(old_features[finding.old_feature_id])
                included_old_ids.add(finding.old_feature_id)
        elif finding.outcome == "not_found":
            output_findings_by_old_id[finding.old_feature_id].append(finding)
            if finding.old_feature_id not in included_old_ids:
                bad_old.append(old_features[finding.old_feature_id])
                included_old_ids.add(finding.old_feature_id)
    if any(feature.geom_type not in {"Line", "Polygon"} for feature in bad_old):
        _fail(422, "DIR output requires original line or polygon geometry.")
    await _delete_generated_layer(db, study, study.output_line_layer_id, "Line")
    await _delete_generated_layer(db, study, study.output_node_layer_id, "Polygon")
    for finding in findings:
        finding.generated_feature_id = None
    layer_ids: dict[str, UUID] = {}
    for geom_type, name in (("Line", "DIR_CLIN"), ("Polygon", "DIR_NODE")):
        if not any(feature.geom_type == geom_type for feature in bad_old):
            continue
        layer = await ProjectService.create_project_layer_with_style(
            db,
            project_id=study.project_id,
            name=name,
            feature_geom_type=geom_type,
            layer_source="IPAG",
            layer_category="S6_DIR",
            layer_subcategory=name,
            version=study.new_version,
            description=f"DIR study {study.id}",
        )
        layer_ids[geom_type] = layer.id
    for feature in bad_old:
        geom_model = GeomLine if feature.geom_type == "Line" else GeomPolygon
        geom_row = geom_model(
            layer_id=layer_ids[feature.geom_type],
            dimension="2D" if workflow_version in {2, 3} else "3D" if feature.geom.has_z else "2D",
            geom=from_shape(force_3d(force_2d(feature.geom)), srid=3414) if workflow_version in {2, 3} else feature.raw_geom,
        )
        db.add(geom_row)
        await db.flush()
        for finding in output_findings_by_old_id[feature.id]:
            finding.generated_feature_id = geom_row.id
        db.add(
            AttrDirExt(
                feature_id=geom_row.id,
                layer_name="DIR_CLIN" if feature.geom_type == "Line" else "DIR_NODE",
                infr_type_code=feature.infr_type,
                feat_type_code=feature.feat_type,
                meta_state="E",
                meta_owner=feature.owner,
                meta_grade="E",
                meta_ltype=feature.ltype,
                meta_infid=feature.infid,
            )
        )
    study.output_line_layer_id = layer_ids.get("Line")
    study.output_node_layer_id = layer_ids.get("Polygon")
    study.status = "generated"
    study.revision += 1
    await db.commit()
    return DirGenerateResponse(
        line_layer_id=study.output_line_layer_id,
        node_layer_id=study.output_node_layer_id,
        dir_feature_count=len(bad_old),
        reviewed_finding_count=len(all_findings),
    )


