        geocup_rows.append(["Missing", final_grades.missing, final_grades.alignment_missing])
        sheets.append(("GeoCUP grade review", geocup_rows))
        if workflow_version == 3 and cast(dict[str, object], study.steps["5"])["status"] == "completed":
            ungraded = sorted(
