async def _check_sources(db: AsyncSession, study: DirStudy) -> dict[UUID, list[_Feature]]:
    all_ids = set(study.old_layer_ids + study.new_layer_ids + study.evidence_layer_ids)
    if study.workflow_version == 3:
        all_ids.update(study.working_area_layer_ids)
    layer_map = {layer.id: layer for layer in await _project_layers(db, study.project_id)}
    if not all_ids.issubset(layer_map):
        _fail(409, "A selected source layer was removed.")
    result: dict[UUID, list[_Feature]] = {}
    for layer_id in all_ids:
        result[layer_id] = await _load_features(db, [layer_map[layer_id]])
        if study.source_hashes.get(str(layer_id)) != _source_hash(result[layer_id]):
            _fail(409, "Selected source data changed. Create a new study.")
    return result


