async def _dir_threshold(db: AsyncSession) -> float:
    rule = (await db.execute(select(ValidationRule).where(ValidationRule.rule_code == "DIR_DEVIATION", ValidationRule.schema_version == "R3_2026"))).scalar_one_or_none()
    if rule is None or not isinstance(rule.rule_payload, dict):
        _fail(503, "The DIR deviation rule is unavailable.")
    value = rule.rule_payload.get("threshold_mm")
    if not isinstance(value, (int, float)) or value <= 0:
        _fail(503, "The DIR deviation rule is invalid.")
    return value / 1000


