def _alignment_measurement_points(source: BaseGeometry, target: BaseGeometry) -> tuple[Point, Point]:
    """Measure final alignment vertices against the original baseline geometry."""
    if isinstance(target, LineString):
        coordinates = target.coords
    elif isinstance(target, MultiLineString):
        coordinates = (coordinate for part in target.geoms for coordinate in part.coords)
    else:
        raise ValueError("Alignment target must be a line.")
    vertex = max((Point(coordinate[:2]) for coordinate in coordinates), key=lambda point: point.distance(source))
