        lines.append(f'<row r="{row_number}">{"".join(cells)}</row>')
    return (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        + '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        + f'<sheetData>{"".join(lines)}</sheetData></worksheet>'
    )


def build_xlsx(sheets: list[tuple[str, list[list[str | int | float]]]]) -> bytes:
    output = BytesIO()
    with ZipFile(output, "w", ZIP_DEFLATED) as archive:
        overrides = ['<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>']
        sheet_entries: list[str] = []
        relationships: list[str] = []
        for number, (name, rows) in enumerate(sheets, 1):
            archive.writestr(f"xl/worksheets/sheet{number}.xml", _sheet_xml(rows))
            overrides.append(f'<Override PartName="/xl/worksheets/sheet{number}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>')
            sheet_entries.append(f'<sheet name="{escape(name)}" sheetId="{number}" r:id="rId{number}"/>')
            relationships.append(f'<Relationship Id="rId{number}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{number}.xml"/>')
        archive.writestr(
            "[Content_Types].xml",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
            + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
def _suggest_grade(code: str, target: base._Feature, coverage: float, noninvasive_coverage: float, has_ttr: bool) -> str | None:
    if code == "5":
        if has_ttr and target.grade == "B":
            return "B+"
        if has_ttr and target.grade == "C":
            return "C+"
        return target.grade
    if code != "4A" or target.geom.length == 0:
        return target.grade
    fraction = coverage / target.geom.length
    if noninvasive_coverage / target.geom.length >= 0.999:
        return "B+" if has_ttr else "B"
    if fraction >= 0.999:
        return target.grade
    if fraction >= 0.5:
        return "B-"
    if fraction > 0:
        return "C+"
    return "C"


def _step_evidence(code: str, old: base._Feature, match: base._Feature | None, evidence: list[base._Feature], threshold: float) -> list[base._Feature]:
    if code == "2":
        points = [item for item in evidence if item.geom_type == "Point" and item.geom.distance(old.geom.centroid) <= 10]
        return sorted(points, key=lambda item: item.geom.distance(old.geom.centroid))[:2]
    if code == "3":
        line = match.geom if match else old.geom
        points = [item for item in evidence if item.geom_type == "Point" and item.geom.distance(line) <= 10]
        return sorted(points, key=lambda item: item.geom.distance(line))[:4]
    if match is None:
        return []
    return [item for item in evidence if item.geom_type in {"Line", "Point"} and item.geom.distance(match.geom) <= threshold]


